/*
 * port/test/decompress_bunzip2/drv.c -- userspace differential for
 * lib/decompress_bunzip2.c.
 *
 * Ground truth is independent of both implementations: each case is a
 * (compressed, plaintext) pair, the plaintext generated by this project
 * (not derived from either decompressor), compressed by the SYSTEM bzip2.
 * Both the pristine C oracle and the Rust port decompress the SAME
 * compressed bytes and are checked against that plaintext directly --
 * not just against each other, which is exactly the STATUS.md #12 trap
 * ("both arms agree and the answer is still wrong").
 *
 * DBZ2_PROVE_CAN_FAIL=1 flips one byte of the Rust output after a
 * successful decompress, before the comparison -- proving the comparison
 * itself can fail, not just that it happens to pass.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>

/* Required by the pristine C's <linux/decompress/mm.h> STATIC arm --
 * its trivial bump allocator, normally supplied by an arch boot/compressed. */
unsigned long free_mem_ptr;
unsigned long free_mem_end_ptr;

typedef long (*fill_fn)(void *, unsigned long);
typedef long (*flush_fn)(void *, unsigned long);
typedef void (*error_fn)(char *);

/* Pristine C oracle -- renamed on the compiler command line. */
extern int cref_bunzip2(unsigned char *buf, long len, fill_fn fill,
			 flush_fn flush, unsigned char *outbuf, long *pos,
			 error_fn error);

/* The Rust port, real symbol name -- this IS what the kernel links. */
extern int bunzip2(unsigned char *buf, long len, fill_fn fill,
		    flush_fn flush, unsigned char *outbuf, long *pos,
		    error_fn error);

/* Userspace stand-ins for the kmalloc/vmalloc/kfree/vfree the Rust side
 * calls (see decompress_bunzip2_rs.rs and its C alloc-shim neighbour). */
void *decompress_bunzip2_alloc(unsigned int size) { return malloc(size); }
void *decompress_bunzip2_dict_alloc(unsigned int size) { return malloc(size); }
void kfree(const void *p) { free((void *)p); }
void vfree(const void *p) { free((void *)p); }

static char last_error[256];
static void record_error(char *msg)
{
	snprintf(last_error, sizeof(last_error), "%s", msg);
}

static unsigned char *read_file(const char *path, long *out_len)
{
	FILE *f = fopen(path, "rb");
	unsigned char *buf;
	long n;

	if (!f) { perror(path); exit(2); }
	fseek(f, 0, SEEK_END);
	n = ftell(f);
	fseek(f, 0, SEEK_SET);
	buf = malloc(n ? (size_t)n : 1);
	if (n && fread(buf, 1, (size_t)n, f) != (size_t)n) { perror("fread"); exit(2); }
	fclose(f);
	*out_len = n;
	return buf;
}

static unsigned char arena[16UL * 1024 * 1024];

/*
 * --fuzz N seed.bz2 -- regression coverage for the class of defect an Opus
 * adversary found in this port's first version (2026-09-05): a handful of
 * bit flips in an otherwise-valid stream drove an accumulator past its
 * type's range, which is a clean error return in C and a checked-arithmetic
 * panic in Rust. CLAUDE.md's ratchet ("build a tool only when a defect gets
 * through") is why this exists at all -- it isn't a general fuzzer, just N
 * single/double-bit mutations of one real stream, each call to the Rust
 * decompressor run in its own fork so a real regression is COUNTED, not a
 * crash that takes the whole harness down with it before it can report.
 */
static int run_fuzz(int n, const char *seed_path, long expected_plain_len)
{
	long seed_len;
	unsigned char *seed = read_file(seed_path, &seed_len);
	/*
	 * Sized like a real caller would size it: generously above the
	 * KNOWN true uncompressed length, the same assumption bunzip2()'s
	 * whole no-flush contract already requires of every caller (this
	 * project's initramfs code included) -- not against whatever a
	 * corrupted stream's second-stage RLE (each byte can expand up to
	 * ~255x) could theoretically produce. That unbounded-output hazard
	 * is inherited unchanged from upstream's `outbuf`/no-`flush`
	 * contract; it is not something this port introduced, so fuzzing
	 * past it here would be measuring the API, not the translation.
	 * (An earlier version of this function sized off the COMPRESSED
	 * length instead, which for this highly-compressible seed was
	 * smaller than even the correct, uncorrupted plaintext -- every
	 * one of its 257/300 "crashes" was that bug, not a Rust defect.)
	 */
	long outcap = expected_plain_len * 4 + 65536;
	int crashes = 0, i;
	unsigned int rng = 0xC0FFEEu;

	for (i = 0; i < n; i++) {
		unsigned char *mut = malloc(seed_len);
		pid_t pid;
		int status;

		memcpy(mut, seed, seed_len);
		rng = rng * 1103515245u + 12345u;
		{
			long byte = (rng >> 8) % seed_len;
			int bit = (int)(rng % 8);
			mut[byte] ^= (unsigned char)(1u << bit);
			rng = rng * 1103515245u + 12345u;
			if (rng & 1) {
				long byte2 = (rng >> 8) % seed_len;
				mut[byte2] ^= (unsigned char)(1u << ((rng >> 3) % 8));
			}
		}

		/* Run both sides, each in its own fork, on the SAME mutated
		 * bytes -- only a case where Rust dies and C does not is a
		 * port regression. A case where both die is a hazard shared
		 * with upstream (unbounded output into a too-small buffer,
		 * same as any other malformed-input crash class neither
		 * implementation guards against), not something this port
		 * introduced. */
		int rust_signaled = 0, c_signaled = 0;

		pid = fork();
		if (pid == 0) {
			unsigned char *out = calloc(1, outcap);
			long pos = 0;

			last_error[0] = 0;
			bunzip2(mut, seed_len, NULL, NULL, out, &pos, record_error);
			_exit(0);
		}
		waitpid(pid, &status, 0);
		rust_signaled = WIFSIGNALED(status) ? WTERMSIG(status) : 0;

		pid = fork();
		if (pid == 0) {
			unsigned char *out = calloc(1, outcap);
			long pos = 0;

			free_mem_ptr = (unsigned long)arena;
			free_mem_end_ptr = (unsigned long)(arena + sizeof(arena));
			last_error[0] = 0;
			cref_bunzip2(mut, seed_len, NULL, NULL, out, &pos, record_error);
			_exit(0);
		}
		waitpid(pid, &status, 0);
		c_signaled = WIFSIGNALED(status) ? WTERMSIG(status) : 0;

		if (rust_signaled && !c_signaled) {
			printf("FAIL fuzz case %d: Rust died on signal %d, C oracle did not (byte-mutated %s)\n",
			       i, rust_signaled, seed_path);
			crashes++;
		}
		free(mut);
	}
	free(seed);

	if (crashes) {
		printf("fuzz: %d/%d mutations crashed Rust where the C oracle did not\n", crashes, n);
		return 1;
	}
	printf("fuzz: %d mutations of %s, no Rust-only crashes\n", n, seed_path);
	return 0;
}

int main(int argc, char **argv)
{
	int prove_can_fail = getenv("DBZ2_PROVE_CAN_FAIL") != NULL;
	int cases = 0, fails = 0;
	int a;

	if (argc == 5 && strcmp(argv[1], "--fuzz") == 0)
		return run_fuzz(atoi(argv[2]), argv[3], atol(argv[4]));

	if (argc < 3 || (argc - 1) % 2 != 0) {
		fprintf(stderr, "usage: %s (compressed plaintext)...\n", argv[0]);
		fprintf(stderr, "       %s --fuzz N seed.bz2 expected-plain-len\n", argv[0]);
		return 2;
	}

	for (a = 1; a + 1 < argc; a += 2) {
		const char *comp_path = argv[a];
		const char *plain_path = argv[a + 1];
		long comp_len, plain_len, outcap, c_pos = 0, r_pos = 0;
		unsigned char *comp, *plain, *c_out, *r_out, *comp1, *comp2;
		int c_ret, r_ret, ok = 1;

		comp = read_file(comp_path, &comp_len);
		plain = read_file(plain_path, &plain_len);
		outcap = plain_len + 4096;
		c_out = calloc(1, outcap);
		r_out = calloc(1, outcap);
		comp1 = malloc(comp_len);
		comp2 = malloc(comp_len);
		memcpy(comp1, comp, comp_len);
		memcpy(comp2, comp, comp_len);
		cases++;

		free_mem_ptr = (unsigned long)arena;
		free_mem_end_ptr = (unsigned long)(arena + sizeof(arena));
		last_error[0] = 0;
		c_ret = cref_bunzip2(comp1, comp_len, NULL, NULL, c_out, &c_pos, record_error);
		if (c_ret != 0) {
			printf("FAIL %s: C oracle returned %d (%s)\n", comp_path, c_ret, last_error);
			ok = 0;
		} else if (memcmp(c_out, plain, plain_len) != 0) {
			printf("FAIL %s: C oracle output != plaintext\n", comp_path);
			ok = 0;
		}

		last_error[0] = 0;
		r_ret = bunzip2(comp2, comp_len, NULL, NULL, r_out, &r_pos, record_error);
		if (r_ret != 0) {
			printf("FAIL %s: Rust returned %d (%s)\n", comp_path, r_ret, last_error);
			ok = 0;
		} else {
			/* Only meaningful when there is at least one output byte
			 * to corrupt -- run.sh keeps the empty-plaintext case out
			 * of the poison corpus for exactly this reason. */
			if (prove_can_fail && plain_len > 0)
				r_out[0] ^= 0xFF;
			if (memcmp(r_out, plain, plain_len) != 0) {
				if (!prove_can_fail)
					printf("FAIL %s: Rust output != plaintext\n", comp_path);
				ok = 0;
			}
		}

		if (ok && c_pos != r_pos) {
			printf("FAIL %s: consumed-length mismatch C=%ld Rust=%ld\n",
			       comp_path, c_pos, r_pos);
			ok = 0;
		}

		if (!ok)
			fails++;
		else
			printf("ok   %s (%ld bytes)\n", comp_path, plain_len);

		free(comp); free(plain); free(c_out); free(r_out); free(comp1); free(comp2);
	}

	/* Same exit convention in both modes -- 0 means every case compared
	 * equal, nonzero means at least one FAIL printed above. In poison
	 * mode every case SHOULD print FAIL (that's the proof); run.sh is
	 * the one that inverts the expectation, not this function. */
	printf("%d/%d cases passed\n", cases - fails, cases);
	return fails ? 1 : 0;
}
